  }
  std::vector<float> params_out(N), m_out(N), v_out(N);

  if (N > 0)
    q.memcpy(d_grads, grads.data(), sizeof(float) * N).wait();

  const int variants[] = {1, 2};
  for (int vi = 0; vi < 2; ++vi) {
    int k = variants[vi];
    if (N > 0) {
